        }
      ]
    }
  }
}];

const salesOrderData = $('Mock Sales Order Data').item.json;
const pricingData = $json;

const orderHeader = salesOrderData.d || {};
const lineItems = (orderHeader.to_Item && orderHeader.to_Item.results) ? orderHeader.to_Item.results : [];

const items = lineItems.map(item => ({
  material: item.Material,
  requestedQuantity: item.RequestedQuantity,
  netAmount: item.NetAmount,
  costAmount: item.CostAmount,
  materialGroup: item.MaterialGroup,
  pricingElements: (item.to_PricingElement && item.to_PricingElement.results) ?
    item.to_PricingElement.results.map(pe => ({
      conditionType: pe.ConditionType,
      conditionRateValue: pe.ConditionRateValue,
      conditionCurrency: pe.ConditionCurrency
    })) : []
}));

const conditions = (pricingData.d && pricingData.d.results) ?
  pricingData.d.results.map(c => ({
    conditionType: c.ConditionType,
    conditionRateValue: c.ConditionRateValue,
    conditionValidityStartDate: c.ConditionValidityStartDate,
    conditionValidityEndDate: c.ConditionValidityEndDate
  })) : [];

const agentPayload = {
  salesOrder: {
    salesOrder: orderHeader.SalesOrder,
    soldToParty: orderHeader.SoldToParty,
    totalNetAmount: orderHeader.TotalNetAmount,
    transactionCurrency: orderHeader.TransactionCurrency,
    pricingDate: orderHeader.PricingDate,
    customerPriceGroup: orderHeader.CustomerPriceGroup,
    customerGroup: orderHeader.CustomerGroup
  },
  lineItems: items,
  pricingConditions: conditions,
  marginFloorPercent: $('Sales Order Trigger').item.json.marginFloorPercent || 0.25
};

return [{ json: { agentPayload } }];

const agentResponse = $json;
const triggerData = $('Sales Order Trigger').item.json;
const salesOrderData = $('Mock Sales Order Data').item.json;

const recommendation = agentResponse.recommendation || {};

const output = {
  salesOrderId: triggerData.salesOrderId,
  customerId: salesOrderData.d ? salesOrderData.d.SoldToParty : '',
  suggestedDiscountPercent: recommendation.suggestedDiscountPercent !== undefined ? recommendation.suggestedDiscountPercent : null,
  rationale: recommendation.rationale || agentResponse.message || '',
  marginImpact: recommendation.marginImpact || '',
  riskFlag: recommendation.riskFlag || 'unknown',
  timestamp: new Date().toISOString()
};

return [{ json: output }];
